const d = $json;
const idEmpresa = String(d.id_empresa || '').trim();
const empresaValida = idEmpresa.length > 0;

return [{ json: {
  id_empresa: idEmpresa,
  empresa_valida: empresaValida,
  evento_resultado: empresaValida ? '' : 'ERRO_LEMBRETE',
  erro: empresaValida ? '' : 'id_empresa é obrigatório e não pode ser vazio para executar o envio de lembretes (nunca fazer busca multi-tenant sem ID_EMPRESA).'
} }];

const ctx = $('CODE - Validar Empresa').first().json;

const buscaOk = $items('GS - Buscar Empresa').length > 0;
if (!buscaOk) {
  return [{ json: {
    ...ctx, pode_prosseguir: false, phone_number_id: '', timezone: 'America/Sao_Paulo',
    evento_resultado: 'ERRO_LEMBRETE',
    erro: 'Falha técnica ao consultar EMPRESAS no Google Sheets.'
  } }];
}

const rows = $items('GS - Buscar Empresa').map(i => i.json).filter(r => r && r.ID_EMPRESA);

if (rows.length === 0) {
  return [{ json: {
    ...ctx, pode_prosseguir: false, phone_number_id: '', timezone: 'America/Sao_Paulo',
    evento_resultado: 'EMPRESA_NAO_ENCONTRADA',
    erro: 'Empresa não encontrada na aba EMPRESAS para o id_empresa informado.'
  } }];
}

const empresa = rows[0];
const phoneNumberId = String(empresa.WHATSAPP_PHONE_NUMBER_ID || '').trim();
const timezone = String(empresa.TIMEZONE || '').trim() || 'America/Sao_Paulo';

if (!phoneNumberId) {
  return [{ json: {
    ...ctx, pode_prosseguir: false, phone_number_id: '', timezone,
    evento_resultado: 'WHATSAPP_NAO_CONFIGURADO',
    erro: 'WHATSAPP_PHONE_NUMBER_ID não está configurado para esta empresa em EMPRESAS.'
  } }];
}

const agoraIso = DateTime.now().setZone(timezone).toISO();

return [{ json: {
  ...ctx, pode_prosseguir: true, phone_number_id: phoneNumberId, timezone, agora_iso: agoraIso, evento_resultado: ''
} }];

const ctx = $('CODE - Avaliar Empresa WhatsApp').first().json;
const idEmpresa = ctx.id_empresa;
const phoneNumberId = ctx.phone_number_id || '';
const timezone = ctx.timezone || 'America/Sao_Paulo';

const agRaw = $items('GS - Buscar Agendamentos').map(i => i.json);
const lemRaw = $items('GS - Buscar Lembretes Existentes').map(i => i.json);
const cliRaw = $items('GS - Buscar Clientes').map(i => i.json);
const profRaw = $items('GS - Buscar Profissionais').map(i => i.json);
const servRaw = $items('GS - Buscar Servicos').map(i => i.json);

// alwaysOutputData garante >=1 item quando a busca teve sucesso (mesmo com 0 resultados reais).
// 0 itens só acontece quando o node seguiu o caminho de erro (onError: continueErrorOutput).
if (agRaw.length === 0 || lemRaw.length === 0 || cliRaw.length === 0 || profRaw.length === 0 || servRaw.length === 0) {
  return [{ json: {
    id_empresa: idEmpresa, id_agendamento: '', id_cliente: '', tipo_lembrete: '',
    telefone_cliente: '', nome_cliente: '', precisa_enviar: false, enviado: false,
    evento_resultado: 'ERRO_LEMBRETE',
    erro: 'Falha técnica ao consultar AGENDAMENTOS, LEMBRETES, CLIENTES, PROFISSIONAIS ou SERVICOS no Google Sheets.'
  } }];
}

const agendamentos = agRaw.filter(r => r && r.ID_AGENDAMENTO);
const lembretes = lemRaw.filter(r => r && r.ID_LEMBRETE);
const clientes = cliRaw.filter(r => r && r.ID_CLIENTE);
const profissionais = profRaw.filter(r => r && r.ID_PROFISSIONAL);
const servicos = servRaw.filter(r => r && r.ID_SERVICO);

const agora = ctx.agora_iso ? DateTime.fromISO(ctx.agora_iso, { zone: timezone }) : DateTime.now().setZone(timezone);

function parseDataHora(dataStr, horaStr) {
  const hora = String(horaStr || '00:00').slice(0, 5);
  let dt = DateTime.fromFormat(`${dataStr} ${hora}`, 'dd/MM/yyyy HH:mm', { zone: timezone });
  if (!dt.isValid) dt = DateTime.fromFormat(`${dataStr} ${hora}`, 'yyyy-MM-dd HH:mm', { zone: timezone });
  if (!dt.isValid) dt = DateTime.fromISO(`${dataStr}T${hora}`, { zone: timezone });
  return dt;
}

// Janelas de detecção (decisão técnica conservadora, documentada no relatório: não há
// tolerância de execução periódica definida no projeto, então usamos janelas com folga
// de +-2h em torno de 24h e +-1h em torno de 2h, largas o suficiente para tolerar
// execuções não perfeitamente pontuais, sem se sobrepor entre si).
const JANELAS = [
  { tipo: 'LEMBRETE_24H', minHoras: 22, maxHoras: 26 },
  { tipo: 'LEMBRETE_2H', minHoras: 1, maxHoras: 3 }
];

if (agendamentos.length === 0) {
  return [{ json: {
    id_empresa: idEmpresa, id_agendamento: '', id_cliente: '', tipo_lembrete: '',
    telefone_cliente: '', nome_cliente: '', precisa_enviar: false, enviado: false,
    evento_resultado: 'AGENDAMENTO_NAO_ELEGIVEL',
    erro: 'Nenhum agendamento com STATUS=AGENDADO encontrado para esta empresa.'
  } }];
}

const candidatos = [];

for (const ag of agendamentos) {
  // Defensivo: mesmo com o filtro STATUS=AGENDADO na busca, revalida contra dado inconsistente.
  if (String(ag.STATUS || '').toUpperCase() !== 'AGENDADO') continue;

  const dataHora = parseDataHora(ag.DATA, ag.HORA_INICIO);
  if (!dataHora.isValid) continue; // registro inválido: sem data/hora utilizável, não processa

  const horasAteAgendamento = dataHora.diff(agora, 'hours').hours;
  if (horasAteAgendamento <= 0) continue; // já passou, nunca lembrar

  for (const janela of JANELAS) {
    if (horasAteAgendamento < janela.minHoras || horasAteAgendamento > janela.maxHoras) continue;

    const base = {
      id_empresa: idEmpresa,
      id_agendamento: ag.ID_AGENDAMENTO,
      id_cliente: ag.ID_CLIENTE || '',
      id_profissional: ag.ID_PROFISSIONAL || '',
      id_servico: ag.ID_SERVICO || '',
      data: ag.DATA || '',
      hora_inicio: String(ag.HORA_INICIO || '').slice(0, 5),
      tipo_lembrete: janela.tipo,
      phone_number_id: phoneNumberId
    };

    const cliente = clientes.find(c => String(c.ID_CLIENTE) === String(ag.ID_CLIENTE)) || null;
    if (!cliente) {
      candidatos.push({ ...base, telefone_cliente: '', nome_cliente: '', precisa_enviar: false, enviado: false, evento_resultado: 'AGENDAMENTO_NAO_ELEGIVEL', erro: 'Cliente não encontrado para este agendamento.' });
      continue;
    }

    const telefoneCliente = String(cliente.TELEFONE || '').replace(/\D/g, '');
    if (!telefoneCliente) {
      candidatos.push({ ...base, telefone_cliente: '', nome_cliente: cliente.NOME || '', precisa_enviar: false, enviado: false, evento_resultado: 'AGENDAMENTO_NAO_ELEGIVEL', erro: 'Cliente sem telefone válido cadastrado.' });
      continue;
    }

    const profissional = profissionais.find(p => String(p.ID_PROFISSIONAL) === String(ag.ID_PROFISSIONAL)) || null;
    if (!profissional) {
      candidatos.push({ ...base, telefone_cliente: telefoneCliente, nome_cliente: cliente.NOME || '', precisa_enviar: false, enviado: false, evento_resultado: 'AGENDAMENTO_NAO_ELEGIVEL', erro: 'Profissional não encontrado para este agendamento.' });
      continue;
    }

    const servico = servicos.find(s => String(s.ID_SERVICO) === String(ag.ID_SERVICO)) || null;
    if (!servico) {
      candidatos.push({ ...base, telefone_cliente: telefoneCliente, nome_cliente: cliente.NOME || '', precisa_enviar: false, enviado: false, evento_resultado: 'AGENDAMENTO_NAO_ELEGIVEL', erro: 'Serviço não encontrado para este agendamento.' });
      continue;
    }

    // Idempotência: bloqueia somente se já existir um lembrete deste TIPO para este agendamento
    // registrado como ENVIADO com sucesso. Uma tentativa com FALHA não bloqueia nova tentativa.
    const jaEnviado = lembretes.some(l =>
      String(l.ID_AGENDAMENTO) === String(ag.ID_AGENDAMENTO) &&
      String(l.TIPO_LEMBRETE) === janela.tipo &&
      String(l.STATUS || '').toUpperCase() === 'ENVIADO'
    );

    if (jaEnviado) {
      candidatos.push({ ...base, telefone_cliente: telefoneCliente, nome_cliente: cliente.NOME || '', precisa_enviar: false, enviado: false, evento_resultado: 'LEMBRETE_JA_ENVIADO', erro: `Este ${janela.tipo} já foi enviado com sucesso para este agendamento.` });
      continue;
    }

    const nomeExibicao = cliente.NOME && String(cliente.NOME).trim() ? String(cliente.NOME).trim() : 'Cliente';
    const nomeServico = servico.NOME || '';
    const nomeProfissional = profissional.NOME || '';
    const horaExib = base.hora_inicio;
    const dataExib = base.data;

    let mensagem;
    if (janela.tipo === 'LEMBRETE_24H') {
      mensagem = `Olá, ${nomeExibicao}! 💜 Passando para lembrar do seu horário de ${nomeServico} com ${nomeProfissional} em ${dataExib} às ${horaExib}.`;
    } else {
      mensagem = `Olá, ${nomeExibicao}! 💜 Seu atendimento de ${nomeServico} com ${nomeProfissional} está agendado para ${dataExib} às ${horaExib}. Estamos te esperando!`;
    }

    candidatos.push({
      ...base,
      telefone_cliente: telefoneCliente,
      nome_cliente: cliente.NOME || '',
      servico: nomeServico,
      profissional: nomeProfissional,
      precisa_enviar: true,
      enviado: false,
      resposta_cliente: mensagem,
      origem: 'AUTOMATICO'
    });
  }
}

if (candidatos.length === 0) {
  return [{ json: {
    id_empresa: idEmpresa, id_agendamento: '', id_cliente: '', tipo_lembrete: '',
    telefone_cliente: '', nome_cliente: '', precisa_enviar: false, enviado: false,
    evento_resultado: 'AGENDAMENTO_NAO_ELEGIVEL',
    erro: 'Nenhum agendamento dentro das janelas de lembrete (24h/2h) nesta execução.'
  } }];
}

return candidatos.map(c => ({ json: c }));

const envio = $json;
// .item (pareamento por item) quebra aqui porque este node lê o retorno de
// EXEC - WF012 Comunicação: a travessia de fronteira de sub-workflow (Execute Workflow)
// não preserva o pairedItem de forma confiável em todas as versões do n8n, causando o erro
// relatado em teste real. .first() é o padrão validado em teste real no n8n para este ponto
// específico (única entrada de CODE - Avaliar Lembretes Elegíveis chega até aqui por execução).
const lembrete = $('CODE - Avaliar Lembretes Elegíveis').first().json;

const enviado = envio.enviado === true;
const timezone = $('CODE - Avaliar Empresa WhatsApp').first().json.timezone || 'America/Sao_Paulo';
const agora = DateTime.now().setZone(timezone).toISO();
const idLembrete = `LEM${Date.now()}${Math.random().toString(36).slice(2, 8)}`;

return [{ json: {
  ...lembrete,
  ID_LEMBRETE: idLembrete,
  ID_EMPRESA: lembrete.id_empresa,
  ID_AGENDAMENTO: lembrete.id_agendamento,
  ID_CLIENTE: lembrete.id_cliente,
  TIPO_LEMBRETE: lembrete.tipo_lembrete,
  TELEFONE: lembrete.telefone_cliente,
  STATUS: enviado ? 'ENVIADO' : 'FALHA',
  DATA_HORA: agora,
  WHATSAPP_MESSAGE_ID: envio.whatsapp_message_id || '',
  OBSERVACOES: enviado ? '' : String(envio.erro || 'Falha ao enviar lembrete via WF012.'),
  enviado: enviado,
  evento_resultado: enviado ? 'LEMBRETE_ENVIADO' : 'ERRO_LEMBRETE',
  erro: enviado ? '' : String(envio.erro || 'Falha ao enviar lembrete via WF012.')
} }];

const l = $('CODE - Processar Resultado Envio').item.json;
const err = $json.error || {};

return [{ json: {
  id_empresa: l.id_empresa,
  id_agendamento: l.id_agendamento,
  id_cliente: l.id_cliente,
  tipo_lembrete: l.tipo_lembrete,
  enviado: l.enviado,
  resposta_cliente: l.resposta_cliente,
  evento_resultado: 'ERRO_LEMBRETE',
  erro: `Lembrete processado (enviado=${l.enviado}) mas falhou ao registrar em LEMBRETES: ${String((err && err.message) || err || 'erro desconhecido')}`
} }];
